window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ae7f60944bb55432"]={"versions": [{"id": "FIG-ae7f60944bb55432", "releases": ["R3.0.7", "R3.1.5", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (<code>ad Bootloader</code>) im Kontext des AUTOSAR ECU State Managers (EcuM Fixed). Das Diagramm spezifiziert die Entscheidungslogik unmittelbar nach einem System-Reset zur Verzweigung auf unterschiedliche Ausführungsziele (Boot Targets).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialknoten (Reset)</strong>: Startpunkt der Sequenz nach einem Hardware- oder Software-Reset des Steuergeräts.</li>\n<li><strong>Aktion (Boot Menu)</strong>: Ausführungseinheit zur Ermittlung des konfigurierten bzw. angeforderten Startziels.</li>\n<li><strong>Entscheidungsknoten (Boot Target)</strong>: Verzweigungsraute zur Differenzierung des Ausführungspfads anhand des Boot-Ziels.</li>\n<li><strong>Aktionen / Zielzustände (Bootloader, Application)</strong>: Alternative Zielumgebungen, die nach der Auswertung des Boot-Menüs angesprungen werden.</li>\n<li><strong>Kontrollflüsse</strong>: Gerichtete Kanten vom Reset zum Boot Menu, weiter zur Boot-Target-Entscheidung und von dort zu Bootloader bzw. Application.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das Steuergerät startet am Initialknoten durch das Ereignis <code>Reset</code>.</li>\n<li>Der Kontrollfluss geht unmittelbar in die Phase bzw. Aktion <code>Boot Menu</code> über, in der das Boot-Ziel ausgewertet wird.</li>\n<li>Nach Durchlaufen von <code>Boot Menu</code> erreicht der Fluss den Verzweigungsknoten <code>Boot Target</code>.</li>\n<li>Abhängig von der ermittelten Boot-Konfiguration verzweigt die Ausführung alternativ entweder in die Ausführungsumgebung <code>Bootloader</code> oder in die <code>Application</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das grundlegende Boot-Target-Konzept des EcuM. Das EcuM-Modul stellt sicher, dass vor dem eigentlichen Systemstart oder Wiederanlauf das Ziel (Bootloader für Reprogrammierung/Flashen vs. Application für den regulären Betrieb) geprüft wird. Entwickler müssen gewährleisten, dass Flags bzw. Parameter für das Boot Target persistent im nichtflüchtigen Speicher oder in Reset-festen RAM-Bereichen hinterlegt und vom Boot-Manager/Boot-Menü vor der Initialisierung der Applikation ausgewertet werden.</p>"}, {"id": "FIG-f9391c84d2391a32", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (<code>ad Bootloader</code>) im Kontext des AUTOSAR ECU State Managers (EcuM Fixed). Das Diagramm spezifiziert die Entscheidungslogik unmittelbar nach einem System-Reset zur Verzweigung auf unterschiedliche Ausführungsziele (Boot Targets).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialknoten (Reset)</strong>: Startpunkt der Sequenz nach einem Hardware- oder Software-Reset des Steuergeräts.</li>\n<li><strong>Aktion (Boot Menu)</strong>: Ausführungseinheit zur Ermittlung des konfigurierten bzw. angeforderten Startziels.</li>\n<li><strong>Entscheidungsknoten (Boot Target)</strong>: Verzweigungsraute zur Differenzierung des Ausführungspfads anhand des Boot-Ziels.</li>\n<li><strong>Aktionen / Zielzustände (Bootloader, Application)</strong>: Alternative Zielumgebungen, die nach der Auswertung des Boot-Menüs angesprungen werden.</li>\n<li><strong>Kontrollflüsse</strong>: Gerichtete Kanten vom Reset zum Boot Menu, weiter zur Boot-Target-Entscheidung und von dort zu Bootloader bzw. Application.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das Steuergerät startet am Initialknoten durch das Ereignis <code>Reset</code>.</li>\n<li>Der Kontrollfluss geht unmittelbar in die Phase bzw. Aktion <code>Boot Menu</code> über, in der das Boot-Ziel ausgewertet wird.</li>\n<li>Nach Durchlaufen von <code>Boot Menu</code> erreicht der Fluss den Verzweigungsknoten <code>Boot Target</code>.</li>\n<li>Abhängig von der ermittelten Boot-Konfiguration verzweigt die Ausführung alternativ entweder in die Ausführungsumgebung <code>Bootloader</code> oder in die <code>Application</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das grundlegende Boot-Target-Konzept des EcuM. Das EcuM-Modul stellt sicher, dass vor dem eigentlichen Systemstart oder Wiederanlauf das Ziel (Bootloader für Reprogrammierung/Flashen vs. Application für den regulären Betrieb) geprüft wird. Entwickler müssen gewährleisten, dass Flags bzw. Parameter für das Boot Target persistent im nichtflüchtigen Speicher oder in Reset-festen RAM-Bereichen hinterlegt und vom Boot-Manager/Boot-Menü vor der Initialisierung der Applikation ausgewertet werden.</p>"}, {"id": "FIG-965ae532d3be6c6d", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (<code>ad Bootloader</code>) im Kontext des AUTOSAR ECU State Managers (EcuM Fixed). Das Diagramm spezifiziert die Entscheidungslogik unmittelbar nach einem System-Reset zur Verzweigung auf unterschiedliche Ausführungsziele (Boot Targets).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialknoten (Reset)</strong>: Startpunkt der Sequenz nach einem Hardware- oder Software-Reset des Steuergeräts.</li>\n<li><strong>Aktion (Boot Menu)</strong>: Ausführungseinheit zur Ermittlung des konfigurierten bzw. angeforderten Startziels.</li>\n<li><strong>Entscheidungsknoten (Boot Target)</strong>: Verzweigungsraute zur Differenzierung des Ausführungspfads anhand des Boot-Ziels.</li>\n<li><strong>Aktionen / Zielzustände (Bootloader, Application)</strong>: Alternative Zielumgebungen, die nach der Auswertung des Boot-Menüs angesprungen werden.</li>\n<li><strong>Kontrollflüsse</strong>: Gerichtete Kanten vom Reset zum Boot Menu, weiter zur Boot-Target-Entscheidung und von dort zu Bootloader bzw. Application.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das Steuergerät startet am Initialknoten durch das Ereignis <code>Reset</code>.</li>\n<li>Der Kontrollfluss geht unmittelbar in die Phase bzw. Aktion <code>Boot Menu</code> über, in der das Boot-Ziel ausgewertet wird.</li>\n<li>Nach Durchlaufen von <code>Boot Menu</code> erreicht der Fluss den Verzweigungsknoten <code>Boot Target</code>.</li>\n<li>Abhängig von der ermittelten Boot-Konfiguration verzweigt die Ausführung alternativ entweder in die Ausführungsumgebung <code>Bootloader</code> oder in die <code>Application</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das grundlegende Boot-Target-Konzept des EcuM. Das EcuM-Modul stellt sicher, dass vor dem eigentlichen Systemstart oder Wiederanlauf das Ziel (Bootloader für Reprogrammierung/Flashen vs. Application für den regulären Betrieb) geprüft wird. Entwickler müssen gewährleisten, dass Flags bzw. Parameter für das Boot Target persistent im nichtflüchtigen Speicher oder in Reset-festen RAM-Bereichen hinterlegt und vom Boot-Manager/Boot-Menü vor der Initialisierung der Applikation ausgewertet werden.</p>"}], "trans": [{"from": "FIG-ae7f60944bb55432", "to": "FIG-f9391c84d2391a32", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f9391c84d2391a32", "to": "FIG-965ae532d3be6c6d", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
